---CONTRACT---
import { z } from 'zod';

import { apiDateTimeSchema, apiIdentifierSchema, createResourceResponseSchema } from './api';

export const DATASET_RELEASE_FORMAT_VERSION = '1.0' as const;

export const datasetReleaseVersionSchema = z
  .string()
  .trim()
  .regex(/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/, 'Use a stable release version.');

export const createDatasetReleaseSchema = z
  .object({
    version: datasetReleaseVersionSchema,
  })
  .strict();

export const datasetReleaseFieldSchema = z
  .object({
    name: z.string().min(1),
    description: z.string().min(1),
  })
  .strict();

export const datasetReleaseSchema = z
  .object({
    releaseId: apiIdentifierSchema,
    version: datasetReleaseVersionSchema,
    createdAt: apiDateTimeSchema,
    formatVersion: z.literal(DATASET_RELEASE_FORMAT_VERSION),
    scope: z.literal('published-accepted-deliveries'),
    eventCount: z.number().int().nonnegative(),
    checksum: z.string().regex(/^[a-f0-9]{64}$/),
    fields: z.array(datasetReleaseFieldSchema),
  })
  .strict();

export const datasetReleaseResponseSchema = createResourceResponseSchema(datasetReleaseSchema);

export type CreateDatasetRelease = z.infer<typeof createDatasetReleaseSchema>;
export type DatasetRelease = z.infer<typeof datasetReleaseSchema>;

---ROUTES---
import {
  createDatasetReleaseSchema,
  datasetReleaseVersionSchema,
} from '@sport-analytics/contracts';
import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireAdministrator } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import type { DatasetReleaseService } from './dataset-release.service';

export function createDatasetReleaseRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: DatasetReleaseService,
): Router {
  const router = Router();
  const authenticate = requireAuthentication(verifyAccessToken, synchronizeAccount);

  router.post(
    '/admin/dataset-releases',
    authenticate,
    requireAdministrator(),
    (request, response) => {
      const parsed = createDatasetReleaseSchema.safeParse(request.body);
      if (!parsed.success) {
        response
          .status(400)
          .json({ error: { code: 'VALIDATION_FAILED', message: 'The request is invalid.' } });
        return;
      }
      void service
        .createRelease(parsed.data)
        .then((release) => response.status(201).json({ data: release }));
    },
  );

  router.get('/dataset-releases/:version', (request, response) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response
        .status(404)
        .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
      return;
    }
    void service.getRelease(version.data).then((release) => {
      if (!release) {
        response
          .status(404)
          .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
        return;
      }
      response.status(200).json({ data: release });
    });
  });

  router.get('/dataset-releases/:version/artifact.json', (request, response) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response.status(404).end();
      return;
    }
    void service.getArtifact(version.data).then((artifact) => {
      if (!artifact) {
        response.status(404).end();
        return;
      }
      response
        .type('application/json')
        .attachment(`dataset-release-${version.data}.json`)
        .send(artifact);
    });
  });

  return router;
}

---SERVICE---
import { createHash } from 'node:crypto';

import {
  DATASET_RELEASE_FORMAT_VERSION,
  type CreateDatasetRelease,
  type DatasetRelease,
} from '@sport-analytics/contracts';

import {
  createDatasetReleaseRepository,
  type DatasetReleaseRepository,
  type DatasetReleaseSnapshot,
} from './dataset-release.repository';

const fields = [
  { name: 'eventId', description: 'Stable identifier of the accepted delivery revision.' },
  { name: 'fixtureId', description: 'Fixture containing the delivery.' },
  { name: 'inningsId', description: 'Innings containing the delivery.' },
  { name: 'inningsOrdinal', description: 'Zero-based source innings order.' },
  { name: 'sequenceNumber', description: 'Stable delivery order within the innings.' },
  { name: 'overNumber', description: 'Zero-based cricket over number.' },
  { name: 'positionInOver', description: 'Zero-based source position within the over.' },
  { name: 'ballNumber', description: 'Display ball label; not an identity field.' },
  { name: 'strikerParticipantId', description: 'Stable striker participant identifier.' },
  { name: 'nonStrikerParticipantId', description: 'Stable non-striker participant identifier.' },
  { name: 'bowlerParticipantId', description: 'Stable bowler participant identifier.' },
  { name: 'runsOffBat', description: 'Runs credited to the striker.' },
  { name: 'runsExtras', description: 'Extra runs on the delivery.' },
  { name: 'runsTotal', description: 'Total runs on the delivery.' },
] as const;

export interface DatasetReleaseService {
  createRelease(input: CreateDatasetRelease): Promise<DatasetRelease>;
  getRelease(version: string): Promise<DatasetRelease | null>;
  getArtifact(version: string): Promise<string | null>;
}

function mapSnapshot(snapshot: DatasetReleaseSnapshot): DatasetRelease {
  return {
    releaseId: snapshot.releaseId,
    version: snapshot.version,
    createdAt: snapshot.createdAt,
    formatVersion: DATASET_RELEASE_FORMAT_VERSION,
    scope: 'published-accepted-deliveries',
    eventCount: snapshot.eventCount,
    checksum: snapshot.checksum,
    fields: [...fields],
  };
}

export function createDatasetReleaseService(
  repository: DatasetReleaseRepository = createDatasetReleaseRepository(),
): DatasetReleaseService {
  return {
    async createRelease(input) {
      const existing = await repository.findByVersion(input.version);
      if (existing) {
        return mapSnapshot(existing);
      }

      const events = await repository.loadPublishedEvents();
      const artifact = JSON.stringify({
        formatVersion: DATASET_RELEASE_FORMAT_VERSION,
        scope: 'published-accepted-deliveries',
        fields,
        events,
      });
      const created = await repository.createOrFind({
        version: input.version,
        formatVersion: DATASET_RELEASE_FORMAT_VERSION,
        scope: 'published-accepted-deliveries',
        eventCount: events.length,
        fields,
        artifact,
        checksum: createHash('sha256').update(artifact).digest('hex'),
      });

      return mapSnapshot(created);
    },

    async getRelease(version) {
      const release = await repository.findByVersion(version);
      return release ? mapSnapshot(release) : null;
    },

    getArtifact(version) {
      return repository.findArtifactByVersion(version);
    },
  };
}

---REPOSITORY---
import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';

export interface DatasetReleaseSnapshot {
  releaseId: string;
  version: string;
  createdAt: string;
  eventCount: number;
  checksum: string;
}

interface DatasetReleaseRow extends DatasetReleaseSnapshot {
  artifactText?: string;
}

export interface DatasetReleaseRepository {
  loadPublishedEvents(): Promise<unknown[]>;
  createOrFind(input: {
    version: string;
    formatVersion: string;
    scope: string;
    eventCount: number;
    fields: readonly { name: string; description: string }[];
    artifact: string;
    checksum: string;
  }): Promise<DatasetReleaseSnapshot>;
  findByVersion(version: string): Promise<DatasetReleaseSnapshot | null>;
  findArtifactByVersion(version: string): Promise<string | null>;
}

const snapshotColumns = `
  release_id::text AS "releaseId", version,
  created_at::text AS "createdAt", event_count AS "eventCount",
  checksum_sha256 AS checksum
`;

export function createDatasetReleaseRepository(executor?: QueryExecutor): DatasetReleaseRepository {
  const database = () => executor ?? getDatabasePool();

  async function findByVersion(version: string): Promise<DatasetReleaseSnapshot | null> {
    const result = await executeQuery<DatasetReleaseRow>(
      database(),
      `SELECT ${snapshotColumns} FROM dataset_release WHERE version = $1`,
      [version],
    );
    return result.rows[0] ?? null;
  }

  return {
    async loadPublishedEvents() {
      const result = await executeQuery<{ event: unknown }>(
        database(),
        `
          SELECT jsonb_build_object(
            'eventId', d.delivery_id::text, 'fixtureId', i.fixture_id::text,
            'inningsId', i.innings_id::text, 'inningsOrdinal', i.ordinal,
            'sequenceNumber', d.innings_sequence, 'overNumber', d.over_number,
            'positionInOver', d.position_in_over, 'ballNumber', d.ball_number,
            'strikerParticipantId', d.striker_id::text, 'nonStrikerParticipantId', d.non_striker_id::text,
            'bowlerParticipantId', d.bowler_id::text, 'runsOffBat', d.runs_off_bat,
            'runsExtras', d.runs_extras, 'runsTotal', d.runs_total
          ) AS event
          FROM delivery_current d
          INNER JOIN innings i ON i.innings_id = d.innings_id
          INNER JOIN submission s ON s.submission_id = d.submission_id AND s.status = 'accepted'
          ORDER BY i.fixture_id ASC, i.ordinal ASC, d.innings_sequence ASC, d.delivery_id ASC
        `,
      );
      return result.rows.map((row) => row.event);
    },

    async createOrFind(input) {
      const result = await executeQuery<DatasetReleaseRow>(
        database(),
        `
          INSERT INTO dataset_release
            (version, format_version, scope, event_count, fields, artifact_text, checksum_sha256)
          VALUES ($1, $2, $3, $4, $5::jsonb, $6, $7)
          ON CONFLICT (version) DO NOTHING
          RETURNING ${snapshotColumns}
        `,
        [
          input.version,
          input.formatVersion,
          input.scope,
          input.eventCount,
          JSON.stringify(input.fields),
          input.artifact,
          input.checksum,
        ],
      );
      if (result.rows[0]) {
        return result.rows[0];
      }

      const existing = await findByVersion(input.version);
      if (!existing) {
        throw new Error('Dataset release was not created or found.');
      }
      return existing;
    },

    findByVersion,

    async findArtifactByVersion(version) {
      const result = await executeQuery<DatasetReleaseRow>(
        database(),
        'SELECT artifact_text AS "artifactText" FROM dataset_release WHERE version = $1',
        [version],
      );
      return result.rows[0]?.artifactText ?? null;
    },
  };
}

