  gap: 1rem;
  margin: 1.25rem 0 0;
}

.statistic-metrics > div,
.event-trace dl > div {
  min-width: 0;
}

.statistic-metrics dt,
.event-trace dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.statistic-metrics dd,
.event-trace dd {
  margin: 0.35rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.participant-statistics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.5rem;
}

.participant-statistics h4 {
  margin: 1.25rem 0 0;
}

.player-match-list {
  margin-top: 1rem;
}

.player-match-card__associations {
  margin: 0.5rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.player-match-card__notices {
  margin-top: 1.25rem;
  padding: 1rem;
  border-inline-start: 4px solid var(--colour-brand);
  background: var(--colour-surface-raised);
}

.player-match-card__notices h4,
.player-match-card__notices ul {
  margin: 0;
}

.player-match-card__notices ul {
  margin-top: 0.5rem;
  padding-inline-start: 1.25rem;
}

.statistic-card__source-count,
