    font-size: 2.5rem;
  }

  .home-principles__list p {
    max-width: none;
  }

  .derivation-story__layout,
  .api-feature__layout {
    gap: var(--space-8);
  }

  .derivation-flow {
    grid-template-columns: 1fr;
  }

  .derivation-flow__transition {
    min-height: 3rem;
  }

  .derivation-flow__transition span {
    width: 2px;
    height: 2rem;
    margin-inline: auto;
    border-top: 0;
    border-left: 2px solid var(--colour-primary);
  }

  .derivation-flow__transition span::after {
    top: auto;
    right: -3px;
    bottom: 0;
    transform: rotate(135deg);
  }

  .derivation-flow__event,
  .derivation-flow__statistics {
    padding: var(--space-5);
  }

  .derivation-flow__source {
    grid-column: auto;
    padding: var(--space-4);
  }

  .explore-gateway__list li {
