import 'dotenv/config';

import { createApp } from './app';
import { loadEnvironment } from './config/env';
import { closeDatabasePool } from './database';

const environment = loadEnvironment();
const app = createApp({ environment });

const server = app.listen(environment.PORT, () => {
  console.log(`Sport Analytics API listening on port ${environment.PORT}`);
});

let shuttingDown = false;

function closeHttpServer(): Promise<void> {
  return new Promise((resolve, reject) => {
    server.close((error) => {
      if (error) {
        reject(error);
        return;
      }

      resolve();
    });
  });
}

async function shutdown(signal: string): Promise<void> {
  if (shuttingDown) {
    return;
  }

  shuttingDown = true;

  console.log(`${signal} received; shutting down`);

  try {
    await closeHttpServer();
  } catch {
    console.error('Failed to close HTTP server cleanly.');
    process.exitCode = 1;
  }

  try {
    await closeDatabasePool();
  } catch {
    console.error('Failed to close database pool cleanly.');
    process.exitCode = 1;
  }
import { spawnSync } from 'node:child_process';

const workspaces = {
  frontend: '@sport-analytics/frontend',
  backend: '@sport-analytics/backend',
};

const argumentsToForward = process.argv.slice(2);
const requestedApp = argumentsToForward[0]?.startsWith('-')
  ? 'frontend'
  : (argumentsToForward.shift() ?? 'frontend');

if (!(requestedApp in workspaces)) {
  console.error(`Unknown development app "${requestedApp}". Use "frontend" or "backend".`);
  process.exitCode = 1;
} else {
  const npmCli = process.env.npm_execpath;

  if (!npmCli) {
    console.error('npm_execpath is unavailable. Start this command through npm.');
    process.exitCode = 1;
  } else {
    const result = spawnSync(
      process.execPath,
      [
        npmCli,
        'run',
        'dev',
        `--workspace=${workspaces[requestedApp]}`,
        '--',
        ...argumentsToForward,
      ],
      { stdio: 'inherit' },
    );

    if (result.error) {
      console.error(`Could not start the ${requestedApp} development app: ${result.error.message}`);
      process.exitCode = 1;
    } else {
      process.exitCode = result.status ?? 1;
    }
  }
}

